import socket, time

class C:
    def __init__(self, port):
        self.s = socket.create_connection(('127.0.0.1', port))
        self.f = self.s.makefile('rb')
    def cmd(self, *args):
        out = b'*%d\r\n' % len(args)
        for a in args:
            if isinstance(a, str): a = a.encode()
            out += b'$%d\r\n%s\r\n' % (len(a), a)
        self.s.sendall(out)
        return self.read()
    def read(self):
        line = self.f.readline()
        t, rest = line[:1], line[1:].strip()
        if t == b'+': return rest.decode()
        if t == b'-': return rest.decode()
        if t == b':': return int(rest)
        if t == b'$':
            n = int(rest)
            if n == -1: return None
            d = self.f.read(n); self.f.read(2); return d
        if t == b'*':
            n = int(rest)
            if n == -1: return None
            return [self.read() for _ in range(n)]
        raise Exception(line)

m, r = C(6379), C(6380)

# all dbs present
dbs = [int(x.split(b'=')[0][2:]) for x in m.cmd('INFO','keyspace').decode().split() if x.startswith(b'db')]
print('dbs:', dbs)
total = mismatch = missing = 0
t0 = time.time()
for db in dbs:
    m.cmd('SELECT', db); r.cmd('SELECT', db)
    keys = m.cmd('KEYS','*')
    for k in keys:
        total += 1
        a = m.cmd('DUMP', k); b = r.cmd('DUMP', k)
        if b is None:
            missing += 1; print('MISSING', db, k); continue
        if a[:-10] != b[:-10]:
            mismatch += 1
            if mismatch < 10: print('VALUE MISMATCH', db, k)
        # type
        if m.cmd('TYPE', k) != r.cmd('TYPE', k):
            mismatch += 1; print('TYPE MISMATCH', db, k)
        # ttl: both must agree (allow 5s slack for measurement skew)
        ta, tb = m.cmd('PTTL', k), r.cmd('PTTL', k)
        if (ta == -2) != (tb == -2):
            mismatch += 1; print('EXISTS MISMATCH', db, k, ta, tb)
        elif ta > 0 and abs(ta - tb) > 5000:
            mismatch += 1; print('TTL MISMATCH', db, k, ta, tb)
        elif ta == -1 and tb != -1:
            mismatch += 1; print('PERSIST MISMATCH', db, k, tb)
print(f'checked={total} mismatches={mismatch} missing={missing} elapsed={time.time()-t0:.1f}s')

# extra: keys on replica that master doesn't have
extra = 0
for db in dbs:
    m.cmd('SELECT', db); r.cmd('SELECT', db)
    mk = set(m.cmd('KEYS','*')); rk = set(r.cmd('KEYS','*'))
    ex = rk - mk
    if ex: extra += len(ex); print('EXTRA on replica db', db, list(ex)[:10])
print('extra:', extra)

# stream deep-check: groups, consumers, pending, entries
m.cmd('SELECT', 0); r.cmd('SELECT', 0)
streams = [k for k in m.cmd('KEYS','*') if m.cmd('TYPE', k) == b'stream']
print('streams:', len(streams))
gs = 0
for k in streams:
    ga, gb = m.cmd('XINFO','GROUPS',k), r.cmd('XINFO','GROUPS',k)
    if ga != gb:
        print('GROUP MISMATCH', k); mismatch += 1
    for g in ga:
        gname = g[g.index(b'name')+1]
        # compare consumers & pending per group
        ca = m.cmd('XINFO','CONSUMERS',k,gname); cb = r.cmd('XINFO','CONSUMERS',k,gname)
        if ca != cb:
            print('CONSUMER MISMATCH', k, gname); mismatch += 1
        pa = m.cmd('XPENDING',k,gname,'-','+',1000); pb = r.cmd('XPENDING',k,gname,'-','+',1000)
        if pa != pb:
            print('PENDING MISMATCH', k, gname); mismatch += 1
        gs += 1
    # entries
    ea = m.cmd('XRANGE',k,'-','+'); eb = r.cmd('XRANGE',k,'-','+')
    if ea != eb:
        print('ENTRIES MISMATCH', k); mismatch += 1
print('groups checked:', gs, 'total problems:', mismatch + missing + extra)
